#include "fh_gpio_spi.h"
#include <time.h>
static void wait_us(unsigned long us){struct timespec t;if(!us)return;t.tv_sec=(time_t)(us/1000000UL);t.tv_nsec=(long)((us%1000000UL)*1000UL);(void)nanosleep(&t,0);}
static int put(fh_gpio_spi_t*s,uint32_t p,uint8_t v){return fh_gpio_write(&s->gpio,p,v);}
static int byte(fh_gpio_spi_t*s,uint8_t tx,uint8_t*rx){unsigned int bit,cpol=s->mode>>1,cpha=s->mode&1;uint8_t lead=cpol?0U:1U,trail=cpol?1U:0U;*rx=0;for(bit=0;bit<8;bit++){uint8_t v=(tx&(0x80U>>bit))?1U:0U,in=0;if(!cpha){if(put(s,s->mosi,v)||put(s,s->sclk,lead))return-1;wait_us(s->delay_us);if(fh_gpio_read(&s->gpio,s->miso,&in)||put(s,s->sclk,trail))return-1;}else{if(put(s,s->sclk,lead)||put(s,s->mosi,v))return-1;wait_us(s->delay_us);if(put(s,s->sclk,trail)||fh_gpio_read(&s->gpio,s->miso,&in))return-1;}*rx=(uint8_t)((*rx<<1)|(in?1U:0U));wait_us(s->delay_us);}return 0;}
int fh_gpio_spi_open(fh_gpio_spi_t*s,uint32_t cs,uint32_t clk,uint32_t mosi,uint32_t miso,unsigned int mode,unsigned long delay){uint8_t idle;if(!s||mode>3||cs==clk||cs==mosi||cs==miso||clk==mosi||clk==miso||mosi==miso)return-1;s->cs=cs;s->sclk=clk;s->mosi=mosi;s->miso=miso;s->mode=mode;s->delay_us=delay;if(fh_gpio_open(&s->gpio)||fh_gpio_mode(&s->gpio,cs,1)||fh_gpio_mode(&s->gpio,clk,1)||fh_gpio_mode(&s->gpio,mosi,1)||fh_gpio_mode(&s->gpio,miso,0)){fh_gpio_spi_close(s);return-1;}idle=(mode&2U)?1U:0U;return put(s,cs,1U)||put(s,clk,idle)?-1:0;}
int fh_gpio_spi_transfer(fh_gpio_spi_t*s,const uint8_t*tx,uint8_t*rx,size_t n){size_t i;if(!s||!tx||!rx||put(s,s->cs,0U))return-1;for(i=0;i<n;i++)if(byte(s,tx[i],&rx[i])){(void)put(s,s->cs,1U);return-1;}(void)put(s,s->cs,1U);return 0;}
void fh_gpio_spi_close(fh_gpio_spi_t*s){if(!s)return;(void)fh_gpio_write(&s->gpio,s->cs,1U);fh_gpio_close(&s->gpio);}
